def transform_final(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    rows = {r for r in range(h) if sum(rr == r for rr, _ in markers) > 1}
    cols = {c for c in range(w) if sum(cc == c for _, cc in markers) > 1}
    left_rays = [(r, c) for r, c in markers if r == 0 or r == h - 1]
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and out[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            hit = any(y in rows or x in cols for y, x in component)
            hit |= any(y == mr and x < mc for mr, mc in left_rays for y, x in component)
            if hit:
                for y, x in component:
                    out[y][x] = 1
    for r in rows:
        for c in range(w):
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out
